/**
 * Model-facing `generate_image` tool over `ctx.image` and `ctx.attachments`: send the
 * text prompt to the reserved provider, durably commit the generated bytes as an image
 * attachment, and return the image itself beside a bounded text envelope. The tool
 * returns an actionable "image unavailable" answer — without failing the session — when
 * no provider is mounted or no attachment store can commit the bytes. It runtime-injects
 * only `tools`, `image`, and `systemPrompt` and imports no provider.
 *
 * Namespace plugin (named exports, no default export).
 * @module @deepseek-ai/dsh-tool-image
 */

import type { Context } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import type { ToolExecution } from '@deepseek-ai/dsh-tools'
import { AttachmentId } from '@deepseek-ai/dsh-attachment'
import type { AttachmentStore, ImageAttachmentRef, ImageMediaType } from '@deepseek-ai/dsh-attachment'
import type { ContentBlock } from '@deepseek-ai/dsh-llm'
import { ImageError } from '@deepseek-ai/dsh-image'
import { MAX_TIMER_DELAY_MS } from '@deepseek-ai/dsh-timeout'
import {
  DEFAULT_MAX_RESULT_CHARS,
  formatGeneratedImage,
  parseGenerateImageArgs,
  presentGenerateImageCall,
} from './render.ts'

export {
  DEFAULT_MAX_RESULT_CHARS,
  formatGeneratedImage,
  parseGenerateImageArgs,
  presentGenerateImageCall,
  UNAVAILABLE_TEXT,
} from './render.ts'
export type { GenerateImageArgs, GeneratedImageItem } from './render.ts'

/** Cordis plugin name for loader diagnostics. */
export const name = 'tool-image'

/** Services required by this plugin. */
export const inject = ['tools', 'image', 'systemPrompt']

/** Default tool-call timeout budget (ms), covering one generation round trip. */
export const DEFAULT_IMAGE_TOOL_TIMEOUT_MS = 180_000

/** The stable system-prompt guidance positioning the generation tool and its optionality. */
export const IMAGE_PROMPT_TEXT =
  'Use generate_image to create an image from a text prompt. It is unavailable until an image provider is configured — then continue without image generation, for example by suggesting the user configure one.'

/** Plugin configuration: the result cap and the timeout budget. */
export interface Config {
  /** Largest complete rendered result in characters, including truncation metadata (default 8000). */
  maxResultChars?: number
  /** Tool-call timeout budget in ms (default 180000). */
  timeoutMs?: number
}

export const Config: z<Config> = z.object({
  maxResultChars: z.number().default(DEFAULT_MAX_RESULT_CHARS),
  timeoutMs: z.number().max(MAX_TIMER_DELAY_MS).default(DEFAULT_IMAGE_TOOL_TIMEOUT_MS),
})

type ResolvedConfig = Required<Config>

/** The structured image metadata projected into the tool's output schema. */
export interface GeneratedImageValue {
  attachmentId: string
  mediaType: string
  bytes: number
  width: number
  height: number
  name?: string
}

/** The structured outcome declared by the `generate_image` output schema. */
export interface GenerateImageValue {
  status: 'ok' | 'unavailable'
  image?: GeneratedImageValue
  revisedPrompt?: string
}

/**
 * Re-brand a structured image outcome into the durable attachment reference an
 * `ImageBlock` carries.
 * @param image - the image metadata from the output schema.
 * @returns the branded attachment reference.
 */
export function imageRefFromValue(image: GeneratedImageValue): ImageAttachmentRef {
  return {
    attachmentId: AttachmentId(image.attachmentId),
    // The execute path already narrows the media type to the storable set
    // before the outcome is projected, so the assertion only re-brands it.
    mediaType: image.mediaType as ImageMediaType,
    bytes: image.bytes,
    width: image.width,
    height: image.height,
    ...image.name === undefined ? {} : { name: image.name },
  }
}

/**
 * Project one structured generation outcome into its model-facing envelope and image.
 * @param value - the generation outcome.
 * @returns the content blocks used by native and nested dispatches.
 */
export function generateImageContent(value: GenerateImageValue): ContentBlock[] {
  const blocks: ContentBlock[] = [{ type: 'text', text: formatGeneratedImage(value, DEFAULT_MAX_RESULT_CHARS) }]
  if (value.status === 'ok' && value.image !== undefined) {
    blocks.push({ type: 'image', attachment: imageRefFromValue(value.image) })
  }
  return blocks
}

/**
 * Register the `generate_image` tool and its system-prompt guidance.
 * @param ctx - the plugin context (must inject `tools`, `image`, `systemPrompt`).
 * @param config - the resolved plugin configuration.
 */
export function apply(ctx: Context, config: Config): void {
  const resolved = config as ResolvedConfig
  assertPositiveInteger('maxResultChars', resolved.maxResultChars)
  assertTimer('timeoutMs', resolved.timeoutMs)

  ctx.systemPrompt.section({
    name: 'tool:image',
    order: ctx.systemPrompt.getSectionOrder('TOOL_IMAGE'),
    text: IMAGE_PROMPT_TEXT,
  })

  ctx.tools.register(defineTool({
    name: 'generate_image',
    description:
      'Generate an image from a text prompt and return the image itself. prompt is required; size is an optional refinement such as "1024x1024". Returns an actionable unavailable message when no image provider is configured.',
    parameters: {
      prompt: { type: 'string', required: true, description: 'The text prompt describing the image to generate.' },
      size: { type: 'string', description: 'Optional requested image size (for example "1024x1024"); the provider interprets the hint.' },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          status: { type: 'string', required: true, enum: ['ok', 'unavailable'] },
          image: {
            type: 'object',
            additionalProperties: false,
            properties: {
              attachmentId: { type: 'string', required: true },
              mediaType: { type: 'string', required: true },
              bytes: { type: 'integer', required: true },
              width: { type: 'integer', required: true },
              height: { type: 'integer', required: true },
              name: { type: 'string' },
            },
          },
          revisedPrompt: { type: 'string' },
        },
      },
      render: (_args, value) => generateImageContent(value),
      // Persist only the prompt-facing facts. The attachment reference is NOT
      // copied here: the settled `content` already carries the image block with
      // the complete reference, mirroring `read_image`'s single-record rule.
      presentationMeta: (_args, value) => ({
        ...value.status === 'ok' && value.image !== undefined ? { mediaType: value.image.mediaType } : {},
      }),
    },
    timeoutMs: resolved.timeoutMs,
    // Content-addressed attachment writes are idempotent and the generation is
    // stateless, so concurrent calls cannot conflict.
    isConcurrencySafe: () => true,
    async execute(args, exec: ToolExecution) {
      const input = parseGenerateImageArgs(args)
      // Gate before any generation I/O so a refusal never spends the caller's
      // provider budget on bytes the deployment cannot durably commit.
      if (ctx.get('attachments') === undefined) {
        return { status: 'unavailable' as const }
      }
      try {
        const result = await ctx.image.generate({
          prompt: input.prompt,
          ...input.size === undefined ? {} : { size: input.size },
        }, exec.signal)
        // Persist before returning: the image block must reference a durably
        // committed object by the time the tool/result event is appended.
        const attachments = ctx.get('attachments') as AttachmentStore
        const ref = await saveGeneratedImage(attachments, result.data, result.mediaType)
        return {
          status: 'ok' as const,
          image: {
            attachmentId: ref.attachmentId,
            mediaType: ref.mediaType,
            bytes: ref.bytes,
            width: ref.width,
            height: ref.height,
            ...ref.name === undefined ? {} : { name: ref.name },
          },
          ...result.revisedPrompt === undefined ? {} : { revisedPrompt: result.revisedPrompt },
        }
      } catch (error) {
        if (error instanceof ImageError && error.code === 'IMAGE_UNAVAILABLE') {
          return { status: 'unavailable' as const }
        }
        throw error
      }
    },
    presentCall: presentGenerateImageCall,
  }))
}

/** Raster image formats the version-one attachment path accepts. */
const IMAGE_MEDIA_TYPES: readonly ImageMediaType[] = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']

/**
 * Commit one generated image into the durable attachment store under a stable name.
 * @param attachments - the mounted attachment store.
 * @param data - the generated image bytes.
 * @param mediaType - the media type the bytes decode as.
 * @returns the durable attachment reference.
 * @throws an actionable error when the endpoint's media type is not storable.
 */
async function saveGeneratedImage(attachments: AttachmentStore, data: Uint8Array, mediaType: string): Promise<ImageAttachmentRef> {
  if (!IMAGE_MEDIA_TYPES.includes(mediaType as ImageMediaType)) {
    throw new Error(`the generation endpoint returned a "${mediaType}" image, which this deployment cannot store; configure an endpoint that returns PNG/JPEG/WebP images`)
  }
  return attachments.saveImage({ data, mediaType: mediaType as ImageMediaType, name: 'generated.png' })
}

/** Reject a non-positive-integer config value at load, so misconfiguration fails loud. */
function assertPositiveInteger(name: string, value: number): void {
  if (!Number.isInteger(value) || value < 1) {
    throw new Error(`tool-image: ${name} must be a positive integer`)
  }
}

/** Reject a timer value Node would clamp instead of scheduling as configured. */
function assertTimer(name: string, value: number): void {
  if (!Number.isInteger(value) || value < 1 || value > MAX_TIMER_DELAY_MS) {
    throw new Error(`tool-image: ${name} must be a positive integer no greater than ${MAX_TIMER_DELAY_MS}`)
  }
}
